1185	const handleRemoteResponse = async <T>(response: Response): Promise<T> => {
1186	  if (!response.ok) {
1187	    let errorMessage = `Request failed with status ${response.status}`;
1188	
1189	    try {
1190	      const body = (await response.json()) as {
1191	        error?: string;
1192	        message?: string;
1193	      };
1194	      errorMessage = body.error || body.message || errorMessage;
1195	    } catch {
1196	      errorMessage = response.statusText || errorMessage;
1197	    }
1198	
1199	    throw new ApiError(errorMessage, response.status, response);
1200	  }
1201	
1202	  if (response.status === 204) {
1203	    return undefined as T;
1204	  }
1205	
1206	  return response.json() as Promise<T>;
1207	};
