18	export function useRelayWorkspaceHostHealth(
19	  hostId: string | null,
20	): UseRelayWorkspaceHostHealthResult {
21	  const hostHealthQuery = useQuery({
22	    queryKey: ["remote-workspaces-host-health", hostId],
23	    enabled: !!hostId,
24	    retry: false,
25	    staleTime: 5_000,
26	    refetchInterval: 15_000,
27	    queryFn: async (): Promise<true> => {
28	      const response = await makeLocalApiRequest("/api/info", {
29	        cache: "no-store",
30	      });
31	
32	      if (!response.ok) {
33	        throw new Error(`Host returned HTTP ${response.status}`);
34	      }
35	
36	      return true;
37	    },
38	  });
39	
40	  const isHostUnavailable =
41	    hostHealthQuery.isError || hostHealthQuery.isRefetchError;
42	
43	  return {
44	    isChecking: hostHealthQuery.isPending,
45	    isError: isHostUnavailable,
46	    errorMessage: isHostUnavailable
47	      ? getErrorMessage(hostHealthQuery.error)
48	      : null,
49	  };
50	}
